function fresh(){const e=new GitLabEngine('focusBoard');e.run('git remote add origin https://example.invalid/team/focusboard.git');e.s.remoteRefs.main=e.head();e.s.terminal=[{type:'info',text:'Team training sandbox. main is protected: use Pull Requests for integration.'}];e.s.history=[];return {role:'minji',repo:e.s,prs:[],selected:null,activeFile:'README.md',notice:'',events:[{who:'system',text:'FocusBoard shared team repository initialized',at:1}],counter:1,help:false};}
let st;try{st=JSON.parse(localStorage.getItem(KEY)||'null');if(!st||!st.repo||!Array.isArray(st.prs))st=fresh();}catch{st=fresh();}
let lang='ko';let currentPage=0;let historyBuffer=[],historyPointer=0;
const tx=k=>(T[lang]||T.ko)[k]||T.ko[k]||k;
const person=k=>(PEOPLE[k]||PEOPLE.minji)[lang]||(PEOPLE[k]||PEOPLE.minji).ko;
const repo=()=>new GitLabEngine('fresh',st.repo);
function persist(){try{localStorage.setItem(examMode?EXAM_KEY:KEY,JSON.stringify(st))}catch(e){console.warn('Team session save failed',e)}}
function log(text){st.events.unshift({who:st.role,text,at:++st.counter});st.events=st.events.slice(0,65)}
function updateRepo(e){st.repo=e.s;persist()}
function prs(n){return st.prs.find(p=>p.id===n)||null}
function firstPR(){return prs(1)}function secondPR(){return prs(2)}
function approvals(p){if(!p)return [];return p.reviews.filter((r,i)=>r.type==='approve'&&r.head===p.head&&!p.reviews.some(x=>x.actor===r.actor&&x.at>r.at&&x.head===p.head&&x.type==='changes')&&!p.reviews.some((x,j)=>j>i&&x.actor===r.actor&&x.type==='approve'&&x.head===p.head));}
function issues(p){if(!p)return [];const o=[];if(p.draft)o.push('Draft 상태를 Ready로 변경');if(p.checks.head!==p.head||p.checks.status!=='passed')o.push('최신 Push 커밋의 CI 검사 통과');if(approvals(p).length<2)o.push(`서로 다른 승인 ${approvals(p).length}/2`);if(p.threads.some(t=>!t.resolved))o.push('미해결 리뷰 대화');if(p.reviews.some(r=>r.type==='changes'&&!p.reviews.some(x=>x.actor===r.actor&&x.type==='approve'&&x.at>r.at)))o.push('수정 요청한 리뷰어의 재승인');const e=repo();if(e.s.remoteRefs[p.branch]!==e.s.branches[p.branch])o.push('최신 커밋을 원격에 Push');return o;}
function pathOk(branch){const e=repo();return !!e.s.branches[branch]}
