function createPR(title,body){const e=repo(),br=e.s.branch;const expected=st.role==='minji'?'feature/task-filter':st.role==='daehyun'?'feature/task-count':null;if(br!==expected){msg('기능 브랜치 작성자만 PR을 만들 수 있습니다.');return}if(title.trim().length<12||body.trim().length<25){msg('PR 제목 12자 이상, 변경 이유/검증 내용 25자 이상을 입력하세요.');return}if(!pushed(br)||!hasCommitOn(br)){msg('git commit과 git push를 먼저 완료하세요.');return}if(st.prs.length>=2){msg('교육 목표는 두 개의 PR 완료입니다. 모든 PR을 병합했는지 확인하세요.');return}if(st.prs.some(x=>x.branch===br)){msg('이미 해당 브랜치의 PR이 있습니다.');return}if(st.role==='daehyun'&&!firstPR()?.status?.includes('merged')){msg('첫 번째 PR이 병합된 후 두 번째 PR을 시작하세요.');return}const p={id:st.prs.length+1,author:st.role,branch:br,base:'main',title:title.trim(),body:body.trim(),draft:true,status:'open',reviewers:[],reviews:[],threads:[],checks:{status:'pending',head:''},head:e.s.branches[br],openedHead:e.s.branches[br],baseHead:e.s.branches.main,mergedCommit:null};st.prs.push(p);st.selected=p.id;log(`opened Draft PR #${p.id}: ${p.title}`);msg(`✓ Draft PR #${p.id} created`);persist()}
function requestReview(reviewer){const p=activePR();if(!p||p.status==='merged'){msg('열린 PR을 선택하세요.');return}if(st.role!==p.author){msg('작성자 역할에서 리뷰를 요청하세요.');return}if(reviewer===p.author||!PEOPLE[reviewer]){msg('작성자 본인에게 리뷰를 요청할 수 없습니다.');return}if(!p.reviewers.includes(reviewer))p.reviewers.push(reviewer);log(`PR #${p.id}: review requested from ${reviewer}`);msg('✓ '+person(reviewer));persist()}
function review(type,body){const p=activePR();if(!p||p.status!=='open'||p.draft){msg('Ready 상태인 열린 PR을 선택하세요.');return}if(p.author===st.role){msg('⛔ PR 작성자는 자기 PR을 승인하거나 리뷰할 수 없습니다.');return}if(!p.reviewers.includes(st.role)){msg('리뷰 요청을 받은 사람만 리뷰할 수 있습니다.');return}if((type==='changes'||type==='comment')&&body.trim().length<12){msg('구체적인 코드 리뷰를 12자 이상 남기세요.');return}if(type==='approve'&&p.threads.some(th=>!th.resolved&&th.actor===st.role)){msg('수정 요청 대화가 해결되기 전에는 승인할 수 없습니다.');return}const n=++st.counter;const reviewFile=document.getElementById('team-review-file')?.value||'';p.reviews.push({actor:st.role,type,body:body.trim(),file:reviewFile,head:p.head,at:n});if(type==='changes')p.threads.push({id:n,actor:st.role,file:reviewFile,body:body.trim(),head:p.head,resolved:false});log(`PR #${p.id}: ${st.role} submitted ${type}`);msg('✓ '+type);persist()}
function resolveThread(id){const p=activePR(),t=p?.threads.find(x=>x.id===Number(id));if(!p||!t||p.author!==st.role){msg('PR 작성자가 수정한 뒤 해결 표시할 수 있습니다.');return}if(p.head===t.head){msg('⚠ 리뷰 요청 이후 새 수정 커밋을 Push한 뒤 대화를 해결하세요.');return}const filter=fileAt(p,'src/filter.js');if(!filter.includes('trim')||!filter.includes('toLowerCase')){msg('⚠ 공백·대소문자 처리를 실제 코드에 반영하세요.');return}t.resolved=true;log(`PR #${p.id}: resolved review thread`);msg('✓ review discussion resolved');persist()}
function checks(){const p=activePR();if(!p||p.status!=='open'){msg('열린 PR을 선택하세요.');return}if(!pushed(p.branch)){msg('최신 커밋을 원격에 Push하세요.');return}const content=fileAt(p,p.id===1?'src/filter.js':'src/count.js');const ok=p.id===1?(/filterTasks/.test(content)&&/toLowerCase/.test(content)&&/trim/.test(content)&&/return/.test(content)):(/countTasks/.test(content)&&/return/.test(content)&&/\.length/.test(content));p.checks={status:ok?'passed':'failed',head:p.head};log(`PR #${p.id}: teaching checks ${p.checks.status}`);msg(ok?'✓ 학습용 정적 검사 통과 (코드 실행은 하지 않음)':'❌ 검사 실패: '+(p.id===1?'filterTasks, trim, toLowerCase, return':'countTasks, return, .length')+' 조건을 확인하세요.');persist()}
function merge(){const p=activePR();if(!p||p.status!=='open'){msg('열린 PR을 선택하세요.');return}if(st.role!=='sua'){msg('유지관리자 수아만 보호된 main에 병합할 수 있습니다.');return}const errors=issues(p);if(errors.length){msg('⛔ Merge blocked: '+errors.join(' · '));return}const e=repo();const was=e.s.branch;e.s.branch=p.branch;e.s.working=e.snap();e.s.index={};const br=e.s.branches[p.branch];e.s.branch='main';e.s.working=e.snap();e.s.index={};const output=e.run('git merge '+p.branch);if(output.startsWith('error:')||e.s.conflicts.length){msg('Merge conflict: '+output);return}e.run('git push origin main');p.mergedCommit=e.s.branches.main;p.status='merged';updateRepo(e);log('PR #'+p.id+' merged into main by maintainer (protected)');msg(`✓ PR #${p.id} merged · main@${e.head()}`);persist()}
// Layered hints: each hint is unlocked only by the learner, not by command execution.
