function reviewGuide(curr,p){if(curr!==3)return '';const l=REVIEW_LESSON[lang]||REVIEW_LESSON.ko;const ready=!!p&&!p.draft&&p.status==='open',requested=!!p?.reviewers.includes('junho'),junho=st.role==='junho';const checks=[junho,ready,requested];return `<details class="team-review-walkthrough" aria-label="${esc(l.title)}"><summary class="team-review-walkthrough-title">📋 ${esc(l.title)} · ${esc(({ko:'6단계 자세히 보기',en:'6-step walkthrough',ja:'6ステップの詳細',zh:'6步详细说明'})[lang])}</summary><p>${esc(l.intro)}</p><div class="team-review-checks"><span class="${checks[0]?'ok':''}">${checks[0]?'✓':'○'} ${esc(person('junho'))}</span><span class="${checks[1]?'ok':''}">${checks[1]?'✓':'○'} PR Ready</span><span class="${checks[2]?'ok':''}">${checks[2]?'✓':'○'} Review requested</span></div><ol>${l.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><button type="button" class="btn primary sm" data-team-act="focusReview">↳ ${esc(l.actionBtn)}</button><p class="team-review-footnote">${esc(l.done)}</p><div class="team-review-book-guide">▧ ${esc(l.pdf)}</div></details>`}
function reviewInspect(curr,p){if(curr!==3||!p)return '';const l=REVIEW_LESSON[lang]||REVIEW_LESSON.ko;return `<div class="team-review-inspection"><h3>🔍 ${esc(l.head)}</h3><p>${esc(l.note)}</p><div class="team-review-live-diff"><div class="team-review-diff-title">Files changed · PR #${p.id}</div>${fileDiff(p)}</div><p class="team-review-pick">⚠ ${esc(l.pick)}</p></div>`}
function renderSteps(){const flags=stepTruth(),first=flags.findIndex(x=>!x),idx=first<0?flags.length:first;return `<div class="team-steps">${STEPS.map((it,i)=>`<button type="button" data-team-stage="${i+1}" class="team-step ${flags[i]?'is-done':''} ${i===idx?'is-current':''}" aria-label="${esc(it[lang][0])}"><span class="team-step-no">${flags[i]?'✓':String(i+1).padStart(2,'0')}</span><span>${esc(it[lang][0])}</span></button>`).join('')}</div>`}
function currentStage(){const f=stepTruth();const n=f.findIndex(x=>!x);return n<0?10:n}
